var libraryJs = String.raw`
let family='all',galleryPage=0;const galleryPageSize=12;
const featured=['bluegold-classic','folded-ink','folded-silver','folded-ivy','folded-campus','folded-circuit','folded-peach','folded-press','folded-lilac','folded-vermilion','folded-track','folded-navy','folded-jade','folded-wine','folded-slate','folded-sand','folded-cobalt','mint-card','tech-terminal','journal-tape','han-vermilion','folio-proposal','campus-spark','press-daily','story-milestone','executive-board','swiss-red','academic-ivy','cobalt-corner'];
function orderedTemplates(){return [...templates].sort((a,b)=>{const rank=id=>featured.includes(id)?featured.indexOf(id):featured.length+templates.findIndex(t=>t.id===id);return rank(a.id)-rank(b.id);});}
function drawTemplates(){
 const shortlist=orderedTemplates().slice(0,6);if(!shortlist.some(t=>t.id===selected)){shortlist.pop();const current=templates.find(t=>t.id===selected);if(current)shortlist.unshift(current);}
 $('template-list').innerHTML=shortlist.map(t=>'<button class="template-option" data-template="'+esc(t.id)+'" aria-pressed="'+(selected===t.id)+'"><img class="template-thumb" alt="" loading="lazy" src="/api/template-thumbnail?id='+encodeURIComponent(t.id)+'"><span><strong>'+esc(t.name)+'</strong><span class="subtitle">'+esc(t.subtitle)+'</span><span class="tag">'+esc(t.family)+' · PDF / Word</span></span></button>').join('');
 const t=templates.find(t=>t.id===selected);if(!t)return;
 $('selected-title').textContent=t.name+' · '+t.category;
 $('selected-community').hidden=true;$('export-docx').hidden=false;$('export-pdf').hidden=false;$('export-html').hidden=true;
 $('template-info').hidden=false;$('template-info').textContent=t.description;
 $('format-note').textContent='预览与 PDF 共用版式 · Word 可继续编辑';
 $('browse-count').textContent=templates.length+' 套版式 · '+new Set(templates.map(t=>t.family)).size+' 类风格';buttons();
}
function gallery(){
 const query=$('template-search').value.trim().toLowerCase(),kind=$('template-kind').value;
 const matching=orderedTemplates().filter(t=>(kind==='all'||t.category===kind)&&(family==='all'||t.family===family)&&[t.name,t.id,t.subtitle,t.description,t.category,t.family].join(' ').toLowerCase().includes(query));
 const count=Math.max(1,Math.ceil(matching.length/galleryPageSize));galleryPage=Math.min(galleryPage,count-1);
 $('gallery-grid').innerHTML=matching.slice(galleryPage*galleryPageSize,(galleryPage+1)*galleryPageSize).map(t=>'<button class="gallery-card" data-template="'+esc(t.id)+'" aria-label="使用 '+esc(t.name)+'" aria-pressed="'+(selected===t.id)+'"><div class="gallery-preview"><img loading="lazy" alt="'+esc(t.name)+' 简历样张" src="/api/template-thumbnail?id='+encodeURIComponent(t.id)+'"></div><div class="gallery-caption"><span class="serial">'+String(templates.indexOf(t)+1).padStart(2,'0')+'</span><strong>'+esc(t.name)+'</strong><p>'+esc(t.subtitle)+'</p><small>'+esc(t.family)+' · PDF / Word</small></div></button>').join('')||'<p class="gallery-empty">没有匹配的模板，试试其他风格或岗位。</p>';
 $('gallery-count').textContent=matching.length+' 套版式';$('gallery-grid').scrollTop=0;
 $('gallery-jump').innerHTML=Array.from({length:count},(_,i)=>'<option value="'+i+'">第 '+(i+1)+' / '+count+' 页</option>').join('');$('gallery-jump').value=String(galleryPage);$('gallery-prev').disabled=galleryPage===0;$('gallery-next').disabled=galleryPage>=count-1;
}
$('open-library').onclick=()=>{gallery();$('library-dialog').showModal();};$('close-library').onclick=()=>$('library-dialog').close();
$('template-search').oninput=()=>{galleryPage=0;gallery();};$('template-kind').onchange=()=>{galleryPage=0;gallery();};
$('gallery-jump').onchange=()=>{galleryPage=Number($('gallery-jump').value);gallery();};
$('gallery-prev').onclick=()=>{galleryPage--;gallery();};$('gallery-next').onclick=()=>{galleryPage++;gallery();};
$('family-tabs').onclick=e=>{const b=e.target.closest('[data-family]');if(!b)return;family=b.dataset.family;galleryPage=0;for(const button of $('family-tabs').querySelectorAll('button'))button.setAttribute('aria-pressed',String(button===b));gallery();};
$('gallery-grid').onclick=e=>{const b=e.target.closest('[data-template]');if(!b)return;selected=b.dataset.template;drawTemplates();$('library-dialog').close();queuePreview(0);};
$('export-html').onclick=()=>download('html');
function configureLibrary(){ $('library-summary').textContent=templates.length+' 套版式 · '+new Set(templates.map(t=>t.family)).size+' 类风格，从商务学术到创意个性。';$('collection-label').textContent='RESUME COLLECTION / '+templates.length;$('family-tabs').innerHTML=['all',...new Set(templates.map(t=>t.family))].map(value=>'<button data-family="'+esc(value)+'" aria-pressed="'+(value===family)+'">'+esc(value==='all'?'全部风格':value)+'</button>').join(''); }
function fieldLabel(pointer){return pointer==='/basics/image'?'照片网址（请改用本地上传）':pointer;}
$('photo-file').onchange=async e=>{
 const file=e.target.files[0];if(!file)return;
 try{
  if(!['image/jpeg','image/png'].includes(file.type)||file.size>5*1024*1024)throw new Error('请选择 5 MB 以内的 JPG 或 PNG 照片。');
  const bitmap=await createImageBitmap(file);if(bitmap.width>10000||bitmap.height>10000){bitmap.close();throw new Error('图片尺寸过大，请换用证件照。');}
  const canvas=document.createElement('canvas'),scale=Math.min(1,360/bitmap.width,450/bitmap.height);canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);
  const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();
  const image=canvas.toDataURL('image/jpeg',.86);if(image.length>180000)throw new Error('照片压缩后仍较大，请选择更小的照片。');
  set('basics.image',image);sourceChanged();editor();queuePreview(0);error('');
 }catch(err){error(err.message);}finally{e.target.value='';}
};
`;

